const smartOpenReviewBase=openSmartUpload;openSmartUpload=function(project=''){smartOpenReviewBase(project);smartOcrText='';const questions=document.getElementById('smartQuestions');if(questions&&!document.getElementById('smartOcrReview'))questions.insertAdjacentHTML('afterend',`<div id="smartOcrReview" class="ocr-review" hidden><label for="smartOcrRaw">متن کامل خوانده‌شده از تصویر</label><textarea id="smartOcrRaw" rows="6" oninput="smartOcrText=this.value"></textarea><button type="button" class="btn" onclick="applySmartOcrText()">تحلیل دوباره این متن</button></div>`)}
