function prepareOcrImage(file){return new Promise(resolve=>{const image=new Image(),url=URL.createObjectURL(file);image.onload=()=>{const scale=Math.min(2,2200/image.width),canvas=document.createElement('canvas');canvas.width=Math.round(image.width*scale);canvas.height=Math.round(image.height*scale);const context=canvas.getContext('2d');context.drawImage(image,0,0,canvas.width,canvas.height);const pixels=context.getImageData(0,0,canvas.width,canvas.height);for(let i=0;i<pixels.data.length;i+=4){const gray=.299*pixels.data[i]+.587*pixels.data[i+1]+.114*pixels.data[i+2],value=Math.max(0,Math.min(255,(gray-128)*1.35+128));pixels.data[i]=pixels.data[i+1]=pixels.data[i+2]=value}context.putImageData(pixels,0,0);canvas.toBlob(blob=>{URL.revokeObjectURL(url);resolve(blob||file)},'image/jpeg',.94)};image.onerror=()=>{URL.revokeObjectURL(url);resolve(file)};image.src=url})}
