function parseBankReceipt(text){const raw=ocrDigits((text||'').replace(/\r/g,'')),origin=receiptLine(raw,['مبدأ','مبدا','از حساب','فرستنده']),destination=receiptLine(raw,['مقصد','به حساب','گیرنده']),note=receiptLine(raw,['یادداشت','شرح','بابت']),tracking=(raw.match(/(?:کد\s*)?(?:پیگیری|رهگیری|مرجع)\s*[:：ـ-]?\s*([\d\s-]{5,35})/i)||[])[1]?.replace(/\D/g,'')||'',dateMatch=raw.match(/(1[34]\d{2})[\/\-.](\d{1,2})[\/\-.](\d{1,2})/),timeMatch=raw.match(/(?:ساعت|زمان)?\s*([012]?\d|2[0-3])\s*[:٫.]\s*([0-5]\d)/),date=dateMatch?`${dateMatch[1]}/${dateMatch[2].padStart(2,'0')}/${dateMatch[3].padStart(2,'0')}`:'',time=timeMatch?`${timeMatch[1].padStart(2,'0')}:${timeMatch[2]}`:'',amount=receiptAmountToman(raw),category=costCategoryFromNote(note||raw),project=db.projects.find(x=>(note||raw).includes(x.name))?.name||'';return{origin:origin.replace(/(?:شماره|حساب|کارت).*$/,'').trim(),destination:destination.replace(/(?:شماره|حساب|کارت).*$/,'').trim(),amount,date,time,tracking,note,category,project}}
function renderReceiptFields(fields){const box=document.getElementById('smartOcrFields');if(!box)return;const items=[['مبدأ',fields.origin],['مقصد',fields.destination],['مبلغ تومان',fields.amount?money(fields.amount):'تشخیص داده نشد'],['تاریخ',fields.date],['ساعت',fields.time],['کد پیگیری',fields.tracking],['یادداشت',fields.note],['دسته',fields.category],['پروژه',fields.project]];box.innerHTML=`<strong>اطلاعات تشخیص‌داده‌شده</strong><div>${items.map(([k,val])=>`<p><span>${k}</span><b>${esc(val||'—')}</b></p>`).join('')}</div>`}
