function auditLabel(action){return ({'workspace.update':'تغییر تنظیمات فضای کاری','member.invite':'افزودن عضو','member.update':'ویرایش عضو','member.remove':'حذف عضو'}[action]||action)}
function openWorkspaceAudit(){const logs=db.auditLogs.slice(0,100);document.body.insertAdjacentHTML('beforeend',`<div class="modal" id="workspaceModal" onclick="if(event.target===this)closeWorkspaceModal()"><div class="dialog" role="dialog" aria-modal="true"><div class="dialog-head"><div><h2>تاریخچه فعالیت</h2><small>پایه حسابرسی عملیات کاربران</small></div><button class="close" onclick="closeWorkspaceModal()">×</button></div><div class="audit-list">${logs.map(log=>`<article><span class="audit-dot"></span><div><strong>${esc(auditLabel(log.action))}</strong><small>${new Date(log.at).toLocaleString('fa-IR')}</small></div></article>`).join('')||'<div class="empty">هنوز رویدادی ثبت نشده است.</div>'}</div></div></div>`)}
const v25LayoutBase=layout;layout=function(body,title,sub){const ws=db.workspace,industry=Workspace.industry(db),plan=Workspace.plan(db);return v25LayoutBase(body,title,sub).replace('دفتر معماری و اجرا',esc(ws.name)).replace('اطلاعات این نسخه روی همین دستگاه ذخیره می‌شود.<br>نسخه آزمایشی حرفه‌ای ۱.۰',`${esc(industry.name)}<br>${esc(plan.name)}`)}
const v25DashboardBase=dashboard;dashboard=function(){return v25DashboardBase().replace('<main class="content">','<main class="content">'+workspaceSummaryCard())}
