// v26: project-scoped technical discussions, private participants and evidence.
const Collaboration=window.PeymanyarCollaboration;
if(Collaboration){Collaboration.ensure(db);save()}
let pendingDiscussionFile=null,pendingCommentFile=null,activeDiscussionId='';
navItems.splice(Math.max(0,navItems.findIndex(x=>x[0]==='documents')),0,['collaboration','هماهنگی کارگاه']);
const v26IconBase=icon;icon=function(name){return name==='collaboration'?'◌':v26IconBase(name)};
function memberName(id){return db.members.find(x=>x.id===id)?.name||'عضو پروژه'}
function discussionType(thread){return Collaboration.TYPES[thread.type]||Collaboration.TYPES.technical}
function discussionAudience(thread){if(thread.visibility!=='restricted')return'همه اعضای مجاز پروژه';const names=(thread.participantIds||[]).map(memberName);return names.length?names.join('، '):'فقط ایجادکننده'}
function discussionProject(thread){return db.projects.find(x=>String(x.id)===String(thread.projectId))?.name||thread.projectName||'پروژه'}
function discussionAttachmentButton(attachment){return attachment?.id?`<button type="button" class="discussion-attachment" onclick="viewDocument(${Number(attachment.id)})">📎 ${esc(attachment.name||'مشاهده پیوست')}</button>`:''}
function discussionCard(thread){const type=discussionType(thread),comments=thread.comments||[];return `<button type="button" class="discussion-card priority-${thread.priority}" onclick="openDiscussion('${thread.id}')"><div class="discussion-card-top"><span class="discussion-type">${type.icon} ${esc(type.name)}</span><span class="discussion-status status-${thread.status}">${esc(Collaboration.STATUSES[thread.status]||thread.status)}</span></div><h3>${esc(thread.title)}</h3><p>${esc(thread.body)}</p><div class="discussion-meta"><span>${esc(discussionProject(thread))}</span><span>${esc(memberName(thread.createdBy))}</span><span>${fa(comments.length)} پاسخ</span>${thread.attachment?.id?'<span>پیوست دارد</span>':''}</div><small>مخاطب: ${esc(discussionAudience(thread))}</small></button>`}
function discussionList(projectId=''){const rows=Collaboration.list(db,projectId);return `<div class="discussion-list">${rows.map(discussionCard).join('')||'<div class="empty">هنوز موضوع فنی یا گفت‌وگویی ثبت نشده است.</div>'}</div>`}
function canCreateDiscussion(){const member=Workspace.activeMember(db);return Workspace.can(member,'discussion.create')||member?.role==='owner'}
function projectDiscussionsSection(project){const rows=Collaboration.list(db,project.id),open=rows.filter(x=>!['approved','closed'].includes(x.status)).length;return `<section class="detail-section discussion-section"><div class="section-inline"><div><h3>هماهنگی و گفت‌وگوی فنی</h3><small>${fa(open)} موضوع باز • ${fa(rows.length)} کل</small></div>${canCreateDiscussion()?`<button class="btn primary" onclick="openDiscussionComposer('${String(project.id)}')">موضوع جدید</button>`:''}</div>${discussionList(project.id)}</section>`}
function discussionMemberChoices(projectId){const active=Workspace.activeMember(db);return db.members.filter(m=>m.id!==active?.id&&(!m.projectIds?.length||m.projectIds.includes(String(projectId)))).map(m=>`<label class="discussion-recipient"><input type="checkbox" name="discussionRecipient" value="${m.id}"><span><strong>${esc(m.name)}</strong><small>${esc(Workspace.roleName(m.role))}</small></span></label>`).join('')||'<p class="empty-inline">هنوز عضو دیگری برای این پروژه تعریف نشده است.</p>'}
function openDiscussionComposer(projectId=''){if(!canCreateDiscussion())return toast('نقش شما اجازه ایجاد موضوع جدید ندارد');const projects=db.projects.map(p=>`<option value="${String(p.id)}" ${String(p.id)===String(projectId)?'selected':''}>${esc(p.name)}</option>`).join('');if(!projects)return toast('ابتدا یک پروژه بساز');document.body.insertAdjacentHTML('beforeend',`<div class="modal" id="discussionComposer" onclick="if(event.target===this)closeDiscussionComposer()"><div class="dialog discussion-dialog" role="dialog" aria-modal="true"><div class="dialog-head"><div><h2>موضوع فنی جدید</h2><small>پرسش، عکس و تصمیم در سابقه پروژه می‌ماند</small></div><button class="close" onclick="closeDiscussionComposer()">×</button></div><div class="form-grid">${field('پروژه',`<select id="discussionProject" onchange="refreshDiscussionRecipients()">${projects}</select>`)}${field('نوع موضوع',`<select id="discussionType">${Object.entries(Collaboration.TYPES).map(([k,x])=>`<option value="${k}">${esc(x.name)}</option>`).join('')}</select>`)}${field('عنوان','<input id="discussionTitle" placeholder="مثلاً تأیید آهن‌کشی طبقه دوم">')}${field('اولویت',`<select id="discussionPriority">${Object.entries(Collaboration.PRIORITIES).map(([k,x])=>`<option value="${k}">${esc(x)}</option>`).join('')}</select>`)}${field('شرح موضوع','<textarea id="discussionBody" rows="4" placeholder="مسئله، محل و تصمیم موردنیاز را توضیح بده"></textarea>','full')}<div class="field full"><label>عکس، نقشه یا فایل</label><label class="compact-upload"><input id="discussionFile" type="file" accept="image/*,.pdf" onchange="discussionFileSelected(this)"><span>＋ انتخاب عکس یا فایل</span><small id="discussionFileName">اختیاری</small></label></div><div class="field full"><label>چه کسانی این موضوع را ببینند؟</label><div id="discussionRecipients" class="discussion-recipients">${discussionMemberChoices(projectId||db.projects[0]?.id)}</div><small>اگر کسی را انتخاب نکنی، همه اعضای مجاز این پروژه موضوع را می‌بینند.</small></div></div><div class="dialog-actions"><button class="btn primary" onclick="saveDiscussion()">ثبت و ارسال موضوع</button><button class="btn" onclick="closeDiscussionComposer()">انصراف</button></div></div></div>`)}
function refreshDiscussionRecipients(){const box=document.getElementById('discussionRecipients');if(box)box.innerHTML=discussionMemberChoices(v('discussionProject'))}
function discussionFileSelected(input){pendingDiscussionFile=input.files?.[0]||null;const label=document.getElementById('discussionFileName');if(label)label.textContent=pendingDiscussionFile?.name||'اختیاری'}
function closeDiscussionComposer(){document.getElementById('discussionComposer')?.remove();pendingDiscussionFile=null}
async function persistDiscussionAttachment(file){if(!file)return null;const id=uid(),attachment={id,name:file.name,type:file.type||'',size:file.size||0};memoryFiles.set(id,{id,blob:file,type:file.type,name:file.name});try{await storeFile(id,file)}catch{}return attachment}
async function saveDiscussion(){const projectId=v('discussionProject'),project=db.projects.find(x=>String(x.id)===String(projectId));if(!project)return toast('پروژه را مشخص کن');try{const attachment=await persistDiscussionAttachment(pendingDiscussionFile),participantIds=[...document.querySelectorAll('input[name="discussionRecipient"]:checked')].map(x=>x.value),thread=Collaboration.create(db,{projectId,projectName:project.name,title:v('discussionTitle'),body:v('discussionBody'),type:v('discussionType'),priority:v('discussionPriority'),participantIds,attachment});Workspace.audit(db,'discussion.create',{threadId:thread.id,projectId,title:thread.title,participantIds});save();closeDiscussionComposer();toast('موضوع برای افراد انتخاب‌شده ثبت شد');render();setTimeout(()=>openDiscussion(thread.id),0)}catch(error){toast(error.message==='title_body_required'?'عنوان و شرح موضوع را کامل کن':'موضوع ثبت نشد')}}
function discussionCommentRow(comment){return `<article class="discussion-comment"><div class="comment-avatar">${esc(memberName(comment.createdBy).slice(0,1))}</div><div><div class="comment-head"><strong>${esc(memberName(comment.createdBy))}</strong><small>${new Date(comment.createdAt).toLocaleString('fa-IR')}</small></div>${comment.body?`<p>${esc(comment.body)}</p>`:''}${discussionAttachmentButton(comment.attachment)}</div></article>`}
function discussionStatusActions(thread){if(!Collaboration.canModerate(db,thread))return'';return `<div class="discussion-status-actions"><button onclick="changeDiscussionStatus('reviewing')">در حال بررسی</button><button class="approve" onclick="changeDiscussionStatus('approved')">تأیید</button><button class="revise" onclick="changeDiscussionStatus('changes_requested')">نیازمند اصلاح</button><button onclick="changeDiscussionStatus('closed')">بستن</button></div>`}
function openDiscussion(id){const thread=db.discussions.find(x=>x.id===id);if(!thread||!Collaboration.canSee(db,thread))return toast('به این موضوع دسترسی نداری');activeDiscussionId=id;const type=discussionType(thread);document.getElementById('discussionViewer')?.remove();document.body.insertAdjacentHTML('beforeend',`<div class="modal" id="discussionViewer" onclick="if(event.target===this)closeDiscussionViewer()"><div class="dialog discussion-dialog thread-view" role="dialog" aria-modal="true"><div class="dialog-head"><div><span class="discussion-type">${type.icon} ${esc(type.name)}</span><h2>${esc(thread.title)}</h2><small>${esc(discussionProject(thread))} • ${esc(discussionAudience(thread))}</small></div><button class="close" onclick="closeDiscussionViewer()">×</button></div><div class="thread-origin"><div class="thread-author"><strong>${esc(memberName(thread.createdBy))}</strong><span class="discussion-status status-${thread.status}">${esc(Collaboration.STATUSES[thread.status])}</span></div><p>${esc(thread.body)}</p>${discussionAttachmentButton(thread.attachment)}</div>${discussionStatusActions(thread)}<div class="thread-comments">${(thread.comments||[]).map(discussionCommentRow).join('')||'<div class="empty-inline">هنوز پاسخی ثبت نشده است.</div>'}</div><div class="comment-compose"><textarea id="discussionComment" rows="3" placeholder="نظر، پاسخ یا نتیجه بررسی را بنویس"></textarea><label class="comment-file"><input type="file" accept="image/*,.pdf" onchange="commentFileSelected(this)">📎 <span id="commentFileName">افزودن عکس</span></label><button class="btn primary" onclick="addDiscussionComment()">ارسال پاسخ</button></div></div></div>`)}
function closeDiscussionViewer(){document.getElementById('discussionViewer')?.remove();pendingCommentFile=null;activeDiscussionId=''}
function commentFileSelected(input){pendingCommentFile=input.files?.[0]||null;const label=document.getElementById('commentFileName');if(label)label.textContent=pendingCommentFile?.name||'افزودن عکس'}
async function addDiscussionComment(){try{const attachment=await persistDiscussionAttachment(pendingCommentFile),threadId=activeDiscussionId;Collaboration.comment(db,threadId,{body:v('discussionComment'),attachment});Workspace.audit(db,'discussion.comment',{threadId});save();pendingCommentFile=null;closeDiscussionViewer();toast('پاسخ در سابقه موضوع ثبت شد');render();setTimeout(()=>openDiscussion(threadId),0)}catch{toast('متن پاسخ یا یک فایل را وارد کن')}}
function changeDiscussionStatus(status){try{const threadId=activeDiscussionId;Collaboration.setStatus(db,threadId,status);Workspace.audit(db,'discussion.status',{threadId,status});save();closeDiscussionViewer();toast('وضعیت موضوع به‌روزرسانی شد');render();setTimeout(()=>openDiscussion(threadId),0)}catch{toast('اجازه تغییر وضعیت را نداری')}}
function collaboration(){const open=Collaboration.list(db).filter(x=>!['approved','closed'].includes(x.status)).length,projectOptions='<option value="">همه پروژه‌ها</option>'+db.projects.map(p=>`<option value="${String(p.id)}">${esc(p.name)}</option>`).join('');return layout(`<div class="section-head"><div><h2>هماهنگی کارگاه</h2><p>پرسش‌های فنی، عکس‌ها، نظرات و تأییدهای پروژه</p></div>${canCreateDiscussion()?'<button class="btn primary" onclick="openDiscussionComposer()">موضوع جدید</button>':''}</div><section class="collaboration-overview"><div><strong>${fa(open)}</strong><small>موضوع باز</small></div><div><strong>${fa(db.discussions.length)}</strong><small>کل گفت‌وگوها</small></div><div><strong>${fa(db.discussions.filter(x=>x.status==='approved').length)}</strong><small>تأییدشده</small></div></section><div class="collaboration-filter"><select onchange="renderCollaborationFilter(this.value)">${projectOptions}</select></div><div id="collaborationList">${discussionList()}</div>`,'هماهنگی کارگاه','جایگزین حرفه‌ای گفت‌وگوهای پراکنده واتس‌اپ و تلگرام')}
function renderCollaborationFilter(projectId){const box=document.getElementById('collaborationList');if(box)box.innerHTML=discussionList(projectId)}
const v26ProjectDetailBase=projectDetail;projectDetail=function(){const project=db.projects.find(x=>Number(x.id)===selectedProjectId),html=v26ProjectDetailBase();return project?html.replace('<section class="detail-section"><h3>گزارش‌های روزانه',`${projectDiscussionsSection(project)}<section class="detail-section"><h3>گزارش‌های روزانه`):html}
const v26DashboardBase=dashboard;dashboard=function(){const recent=Collaboration.list(db).slice(0,3),panel=`<section class="card dashboard-discussions"><div class="card-head"><div><h3>هماهنگی‌های فنی</h3><small>${fa(Collaboration.unreadCount(db))} موضوع نیازمند پیگیری</small></div><button class="link-btn" onclick="go('collaboration')">مشاهده همه</button></div>${recent.map(discussionCard).join('')||'<div class="empty-inline">موضوع بازی وجود ندارد.</div>'}</section>`;return v26DashboardBase().replace('<section class="grid-2"',panel+'<section class="grid-2"')}
const v26RenderBase=render;render=function(){if(page==='collaboration')document.getElementById('app').innerHTML=collaboration();else v26RenderBase()}
function v26DiscussionDraft(text){
 const project=db.projects.find(p=>text.includes(p.name)),participants=db.members.filter(m=>m.id!==Workspace.activeMember(db)?.id&&(text.includes(m.name)||text.includes(Workspace.roleName(m.role)))),type=/ایمنی|خطر|حادثه/.test(text)?'safety':/کیفیت|تأیید|درست|اصلاح/.test(text)?'quality':/هماهنگ|زمان‌بندی/.test(text)?'coordination':'technical',priority=/فوری|اضطراری|سریع/.test(text)?'urgent':/مهم/.test(text)?'important':'normal',clean=text.replace(/^(?:یک\s+)?(?:موضوع|پرسش|گفتگوی?)\s*(?:فنی)?\s*/,'').trim(),title=(clean||text).slice(0,80);
 return{project,participants,type,priority,title,body:text}
}
function confirmVoiceDiscussion(){const draft=window.v26DiscussionDraft;if(!draft?.project)return toast('نام پروژه را در فرمان بگو');const thread=Collaboration.create(db,{projectId:draft.project.id,projectName:draft.project.name,title:draft.title,body:draft.body,type:draft.type,priority:draft.priority,participantIds:draft.participants.map(x=>x.id)});Workspace.audit(db,'discussion.create',{threadId:thread.id,projectId:String(draft.project.id),source:'voice'});save();toast('موضوع فنی از روی فرمان ثبت شد');go('collaboration');setTimeout(()=>openDiscussion(thread.id),0)}
const v26ParseQuickBase=parseQuick;parseQuick=function(){const input=document.getElementById('quickText'),text=input?.value.trim()||'';if(!/(موضوع فنی|پرسش فنی|گفتگو|هماهنگی کارگاه|برای بررسی|برای تأیید)/.test(text))return v26ParseQuickBase();const draft=v26DiscussionDraft(text),box=document.getElementById('parsedResult');window.v26DiscussionDraft=draft;if(!box)return;box.innerHTML=`<div class="parsed smart-plan"><div class="command-title"><strong>پیش‌نویس موضوع فنی</strong><span class="command-badge">${esc(Collaboration.TYPES[draft.type].name)}</span></div><div class="parsed-grid"><div><small>پروژه</small>${esc(draft.project?.name||'نامشخص')}</div><div><small>اولویت</small>${esc(Collaboration.PRIORITIES[draft.priority])}</div><div><small>مخاطبان</small>${esc(draft.participants.length?draft.participants.map(x=>x.name).join('، '):'همه اعضای پروژه')}</div><div><small>عنوان</small>${esc(draft.title)}</div></div><button class="btn primary full-action" onclick="confirmVoiceDiscussion()" ${draft.project?'':'disabled'}>تأیید و ارسال موضوع</button>${draft.project?'':'<p class="missing">نام یکی از پروژه‌ها را در فرمان بگو.</p>'}</div>`}
const v26AuditLabelBase=auditLabel;auditLabel=function(action){return({'discussion.create':'ایجاد موضوع فنی','discussion.comment':'ثبت پاسخ فنی','discussion.status':'تغییر نتیجه موضوع'}[action]||v26AuditLabelBase(action))}
render();
